// HasContract applies the HasEdge predicate on the "contract" edge.
func HasContract() predicate.ContractServiceTerm {
	return predicate.ContractServiceTerm(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ContractTable, ContractColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasContractWith applies the HasEdge predicate on the "contract" edge with a given conditions (other predicates).
func HasContractWith(preds ...predicate.Contract) predicate.ContractServiceTerm {
	return predicate.ContractServiceTerm(func(s *sql.Selector) {
		step := newContractStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ContractServiceTerm) predicate.ContractServiceTerm {
	return predicate.ContractServiceTerm(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ContractServiceTerm) predicate.ContractServiceTerm {
	return predicate.ContractServiceTerm(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ContractServiceTerm) predicate.ContractServiceTerm {
	return predicate.ContractServiceTerm(sql.NotPredicates(p))
}
